func (s R10NetZero) JSONSize() int {
	size := 28
	if s.Addr.Is4() {
		size += 15
	} else {
		size += 39
	}
	if z := len(s.Addr.Zone()); z > 0 {
		size += 1 + z*2
	}
	if s.IP.To4() != nil {
		size += 15
	} else if len(s.IP) != 0 {
		size += 39
	} else {
		size += 2
	}
	if s.Pfx.Addr().Is4() {
		size += 19
	} else {
		size += 43
	}
	return size
}

