func (s NetAddrs) JSONSize() int {
	size := 270
	size += len(s.ByName) * 4
	for k, v := range s.ByName {
		size += len(k) * 2
		size += 49
		if z := len(v.Zone); z > 0 {
			size += 1 + z*2
		}
	}
	size += len(s.Deep) * 4
	for k, v := range s.Deep {
		size += len(k) * 2
		size += 4
		if n := len(v); n > 0 {
			size += n - 1
		}
		size += len(v) * 45
	}
	if n := len(s.Nets); n > 0 {
		size += n - 1
	}
	size += len(s.Nets) * 45
	if s.OPUDP != nil && (len((*s.OPUDP).IP) > 0 || (*s.OPUDP).Port != 0 || (*s.OPUDP).Zone != "") {
		size += 58
		if z := len((*s.OPUDP).Zone); z > 0 {
			size += 1 + z*2
		}
	}
	if s.OTCP.IP != nil || s.OTCP.Port != 0 || s.OTCP.Zone != "" {
		size += 57
		if z := len(s.OTCP.Zone); z > 0 {
			size += 1 + z*2
		}
	}
	if n := len(s.PAddrs); n > 0 {
		size += n - 1
	}
	for i0 := range s.PAddrs {
		if s.PAddrs[i0] == nil {
			size += 4
		} else {
			size += 49
			if z := len((*s.PAddrs[i0]).Zone); z > 0 {
				size += 1 + z*2
			}
		}
	}
	size += len(s.PByKey) * 4
	for k, v := range s.PByKey {
		size += len(k) * 2
		if v == nil {
			size += 4
		} else {
			size += 45
		}
	}
	if s.PNet == nil {
		size += 4
	} else {
		size += 45
	}
	if s.PTCP == nil {
		size += 4
	} else {
		size += 49
		if z := len((*s.PTCP).Zone); z > 0 {
			size += 1 + z*2
		}
	}
	if z := len(s.TCP.Zone); z > 0 {
		size += 1 + z*2
	}
	if n := len(s.Tuple); n > 0 {
		size += n - 1
	}
	for i0 := range s.Tuple {
		size += 49
		if z := len(s.Tuple[i0].Zone); z > 0 {
			size += 1 + z*2
		}
	}
	if z := len(s.UDP.Zone); z > 0 {
		size += 1 + z*2
	}
	size += len(s.Wide) * 4
	for k, v := range s.Wide {
		size += len(k) * 2
		if v == nil {
			size += 4
		} else {
			size += 49
			if z := len((*v).Zone); z > 0 {
				size += 1 + z*2
			}
		}
	}
	return size
}

