func (recv NetAddrsHTML) DecodeFrom(data []byte) (result NetAddrsHTML, i int, err error) {
	result = recv
	seenTCP := false
	for i < len(data) && data[i] <= ' ' && (data[i] == ' ' || data[i] == '\t' || data[i] == '\n' || data[i] == '\r') {
		i++
	}
	if i >= len(data) || data[i] != '{' {
		return result, i, ggen.NewParseErr("", i, ggen.ErrBadObject)
	}
	i++
	for i < len(data) && data[i] <= ' ' && (data[i] == ' ' || data[i] == '\t' || data[i] == '\n' || data[i] == '\r') {
		i++
	}
	if i < len(data) && data[i] == '}' {
		i++
		if !seenTCP {
			result.TCP = (NetAddrsHTML{}).TCP
		}
		return result, i, nil
	}
	for {
		var key string
		if i >= len(data) || data[i] != '"' {
			return result, i, ggen.NewParseErr("", i, ggen.ErrExpectString)
		}
		ke := i + 1
		for ke < len(data) && data[ke] != '"' && data[ke] != '\\' && data[ke] >= 0x20 && data[ke] < 0x80 {
			ke++
		}
		if ke < len(data) && data[ke] == '"' {
			key = unsafe.String(unsafe.SliceData(data[i+1:]), ke-i-1)
			i = ke + 1
		} else {
			key, i, err = ggen.String(data, i, true)
			if err != nil {
				return result, i, ggen.NewParseErr("", i, err)
			}
		}
		for i < len(data) && data[i] <= ' ' && (data[i] == ' ' || data[i] == '\t' || data[i] == '\n' || data[i] == '\r') {
			i++
		}
		if i >= len(data) || data[i] != ':' {
			return result, i, ggen.NewParseErr("", i, ggen.ErrBadObject)
		}
		i++
		for i < len(data) && data[i] <= ' ' && (data[i] == ' ' || data[i] == '\t' || data[i] == '\n' || data[i] == '\r') {
			i++
		}
		switch key {
		case "tcp":
			if seenTCP {
				return result, i, &ggen.DuplicateKeyError{Pos: i, Keys: []string{"tcp"}}
			}
			seenTCP = true
			var s string
			if i >= len(data) || data[i] != '"' {
				return result, i, ggen.NewParseErr("tcp", i, ggen.ErrExpectString)
			}
			ke := i + 1
			kew := ke + 32
			if kew > len(data) {
				kew = len(data)
			}
			for ke < kew && data[ke] != '"' && data[ke] != '\\' && data[ke] >= 0x20 && data[ke] < 0x80 {
				ke++
			}
			if ke < len(data) && data[ke] == '"' {
				s = unsafe.String(unsafe.SliceData(data[i+1:]), ke-i-1)
				i = ke + 1
			} else {
				s, i, err = ggen.String(data, i, true)
				if err != nil {
					return result, i, ggen.NewParseErr("tcp", i, err)
				}
			}
			result.TCP, err = ggen.ParseNetAddr[net.TCPAddr](s)
			if err != nil {
				return result, i, ggen.NewParseErr("tcp", i, err)
			}
		default:
			return result, i, &ggen.UnknownKeyError{Pos: i, Keys: []string{key}}
		}
		for i < len(data) && data[i] <= ' ' && (data[i] == ' ' || data[i] == '\t' || data[i] == '\n' || data[i] == '\r') {
			i++
		}
		if i >= len(data) {
			return result, i, ggen.NewParseErr("", i, ggen.ErrBadObject)
		}
		if data[i] == ',' {
			i++
			for i < len(data) && data[i] <= ' ' && (data[i] == ' ' || data[i] == '\t' || data[i] == '\n' || data[i] == '\r') {
				i++
			}
			continue
		}
		if data[i] == '}' {
			i++
			if !seenTCP {
				result.TCP = (NetAddrsHTML{}).TCP
			}
			return result, i, nil
		}
		return result, i, ggen.NewParseErr("", i, ggen.ErrBadObject)
	}
}

func (recv NetAddrsHTML) DecodeFromStream(s *ggen.Stream) (result NetAddrsHTML, err error) {
	result = recv
	seenTCP := false
	err = s.ObjectOpen()
	if err != nil {
		return result, ggen.NewParseErr("", s.Offset(), err)
	}
	err = s.SkipSpace()
	if err != nil {
		return result, ggen.NewParseErr("", s.Offset(), err)
	}
	if s.Pos >= len(s.Bytes()) {
		if err = s.ReadMore(s.Pos); err != nil {
			return result, ggen.NewParseErr("", s.Offset(), ggen.NotEOF(err, ggen.ErrExpectString))
		}
		s.Pos = 0
	}
	if s.Bytes()[s.Pos] == '}' {
		s.Pos++
		if !seenTCP {
			result.TCP = (NetAddrsHTML{}).TCP
		}
		return result, nil
	}
	for {
		var key string
		key, err = s.KeyView(true)
		if err != nil {
			return result, ggen.NewParseErr("", s.Offset(), err)
		}
		switch key {
		case "tcp":
			err = s.ConsumeColon()
			if err != nil {
				return result, ggen.NewParseErr("tcp", s.Offset(), err)
			}
			if seenTCP {
				return result, &ggen.DuplicateKeyError{Pos: s.Offset(), Keys: []string{"tcp"}}
			}
			seenTCP = true
			var sv string
			sv, err = s.StringView(true)
			if err != nil {
				return result, ggen.NewParseErr("tcp", s.Offset(), err)
			}
			result.TCP, err = ggen.ParseNetAddr[net.TCPAddr](sv)
			if err != nil {
				return result, ggen.NewParseErr("tcp", s.Offset(), err)
			}
		default:
			ownKey := strings.Clone(key)
			err = s.ConsumeColon()
			if err != nil {
				return result, ggen.NewParseErr(ownKey, s.Offset(), err)
			}
			return result, &ggen.UnknownKeyError{Pos: s.Offset(), Keys: []string{ownKey}}
		}

		err = s.SkipSpace()
		if err != nil {
			return result, ggen.NewParseErr("", s.Offset(), err)
		}
		if s.Pos >= len(s.Bytes()) {
			if err = s.ReadMore(s.Pos); err != nil {
				return result, ggen.NewParseErr("", s.Offset(), ggen.NotEOF(err, ggen.ErrBadObject))
			}
			s.Pos = 0
		}
		c := s.Bytes()[s.Pos]
		if c == ',' {
			s.Pos++
			err = s.SkipSpace()
			if err != nil {
				return result, ggen.NewParseErr("", s.Offset(), err)
			}
			continue
		}
		if c == '}' {
			s.Pos++
			if !seenTCP {
				result.TCP = (NetAddrsHTML{}).TCP
			}
			return result, nil
		}
		return result, ggen.NewParseErr("", s.Offset(), ggen.ErrBadObject)
	}
}

func (s NetAddrsHTML) JSONSize() int {
	size := 57
	if z := len(s.TCP.Zone); z > 0 {
		size += 1 + z*6
	}
	return size
}

func (s NetAddrsHTML) AppendJSON(dst []byte) ([]byte, error) {
	var err error
	_ = err
	dst = append(dst, "{\"tcp\":\""...)
	if dst, err = ggen.AppendNetAddrHTML(dst, s.TCP); err != nil {
		return dst, err
	}
	return append(dst, '}'), nil
}
